const fs = require('fs');
const pdfreader = require('pdfreader');

const rows = {};
let fullText = '';

new pdfreader.PdfReader().parseFileItems('/app/workspace/data/format.pdf', (err, item) => {
  if (err) {
    console.error('Error:', err);
  } else if (!item) {
    const sortedRows = Object.keys(rows).sort((a, b) => {
      const parts_a = a.split('_');
      const parts_b = b.split('_');
      const pageA = Number(parts_a[0]);
      const yA = Number(parts_a[1]);
      const pageB = Number(parts_b[0]);
      const yB = Number(parts_b[1]);
      return pageA !== pageB ? pageA - pageB : yA - yB;
    });

    for (const key of sortedRows) {
      console.log(rows[key].join(' '));
    }
  } else if (item.text) {
    const yRounded = Math.floor(item.y * 100);
    const key = item.page + '_' + yRounded;
    if (!rows[key]) {
      rows[key] = [];
    }
    rows[key].push(item.text);
  }
});
EOF

